#include "ksPartSignalTask.h"
#include <stdexcept>
#include <iostream>
int main(){using T=ks::PartSignalTask;using S=T::Stage;unsigned cases=0;for(unsigned kind=0;kind<4;++kind)for(unsigned part=0;part<256;++part)for(unsigned base=0;base<256;++base){T t(static_cast<T::Kind>(kind));unsigned used=0,reads=0;while(t.stage()!=S::Complete){if(t.awaiting()){if(!t.resumeChild())throw std::runtime_error("resume");continue;}auto cost=t.nextClocks();if(t.advanceBefore(cost-1,[](T::Read){return 0;}))throw std::runtime_error("early");used+=t.advanceBefore(cost,[&](T::Read r){if((reads++==0)!=(r==T::Read::Part))throw std::runtime_error("read order");return r==T::Read::Part?part:base;});}unsigned diff=(part-base)&255;bool clamp=diff&128;if(clamp)diff=0;unsigned expected=kind?((kind==1?1:kind==2?2:4)<<8)|diff:1;if(t.wire()!=expected||t.address()!=(kind?0x8040:0x8041+diff)||reads!=2||used!=(kind?82u:88u)+(clamp?3:0))throw std::runtime_error("result/clocks");++cases;}std::cout<<"PASS: "<<cases<<" pure part signal properties\n";}
